adjustDate: function(sign, days) {
    var day = this.getDate() || new Date();
    var difference = parseInt(days) * 24 * 60 * 60 * 1000;
    var newDay;
    if (sign === 'add') {
        newDay = new Date(day.valueOf() + difference);
    } else if (sign === 'subtract') {
        newDay = new Date(day.valueOf() - difference);
    }
    var step = sign === 'add' ? 1 : -1;
    var msPerDay = 24 * 60 * 60 * 1000;
    while (true) {
        var disabled = false;
        if (this._o.minDate && newDay < this._o.minDate) disabled = true;
        else if (this._o.maxDate && newDay > this._o.maxDate) disabled = true;
        else if (this._o.disableWeekends && (newDay.getDay() === 0 || newDay.getDay() === 6)) disabled = true;
        else if (this._o.disableDayFn && this._o.disableDayFn(newDay)) disabled = true;
        if (!disabled) break;
        newDay = new Date(newDay.valueOf() + step * msPerDay);
    }
    this.setDate(newDay);
},
